<?php require 'header.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){flash('error','Invalid product.');header('Location: manage-products.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->prepare('DELETE FROM products WHERE id=?')->execute([$id]);flash('success','Product deleted.');header('Location: manage-products.php');exit;}?><section class="admin-panel"><h2>Delete product</h2><p>This removes the product, its colours, images, and reviews from the database. Uploaded files are left on disk for recovery.</p><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><button class="danger-button">Delete permanently</button> <a href="manage-products.php">Cancel</a></form></section><?php require 'footer.php'; ?>
